"""The protocol document must describe the firmware that shipped.

DUAL_PAN_RADIO_PROTOCOL.md was written while the protocol was being designed,
and the firmware then shipped something else: verbs that do not exist, an INFO
reporting a different version, and an RX record named after a formatter that
nothing calls. A host written from that document would not have worked.

So the document's command and record tables are generated by
tools/wire_surface.py, which parses the firmware and then proves its parse
against the real dispatcher. These tests re-run that and compare, so the two
cannot drift apart again without a failure here.

No COM, no RF, no hardware.
"""
import json, re, subprocess, sys, unittest
from pathlib import Path

HERE = Path(__file__).resolve().parent
FIRMWARE = HERE.parent
DOC = FIRMWARE.parent / 'DUAL_PAN_RADIO_PROTOCOL.md'
sys.path.insert(0, str(FIRMWARE / 'tools'))
import wire_surface


def doc():
    return DOC.read_text(encoding='utf-8')


def block(mark):
    m = re.search(r'<!-- %s -->\n(.*?)<!-- /%s -->' % (mark, mark), doc(), re.S)
    return m.group(1).strip() if m else None


class Base(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        if not wire_surface.CLI.exists():
            raise unittest.SkipTest('run tests/run_native.sh first')
        cls.s = wire_surface.surface()


class TheParseAgreesWithTheBinary(Base):
    def test_every_verb_accepts_exactly_its_declared_field_set(self):
        """The parse of rejoin_transport.c is offered to the real dispatcher:
        the exact set must not be refused for its fields, and every one-field
        variation must be refused with field_set. A parse the binary disagrees
        with is wrong, whatever it looks like in the source."""
        self.assertTrue(self.s['commands_agree_with_binary'],
                        {v: x for v, x in self.s['verified_against_dispatcher'].items()
                         if not x['agrees_with_binary']})

    def test_all_fourteen_verbs_are_covered(self):
        self.assertEqual(len(self.s['commands']), 14)
        self.assertEqual(len(self.s['verified_against_dispatcher']), 14)

    def test_ctx_scope_is_enforced_as_documented(self):
        v = self.s['verified_against_dispatcher']
        for verb in ('INFO', 'END', 'STATS'):
            self.assertEqual(v[verb]['with_ctx'], 'ctx_not_scoped', verb)
        for verb, spec in self.s['commands'].items():
            if spec['ctx'] == 'required':
                self.assertEqual(v[verb]['without_ctx'], 'ctx_required', verb)
        self.assertNotEqual(v['STATUS']['without_ctx'], 'ctx_required')
        self.assertNotEqual(v['STATUS']['with_ctx'], 'ctx_not_scoped')


class TheDocumentMatchesTheFirmware(Base):
    def test_the_command_table_is_the_generated_one(self):
        self.assertEqual(block(wire_surface.COMMANDS_MARK),
                         wire_surface.render(self.s, wire_surface.COMMANDS_MARK),
                         'run: python tools/wire_surface.py --doc %s' % DOC)

    def test_the_record_table_is_the_generated_one(self):
        self.assertEqual(block(wire_surface.RECORDS_MARK),
                         wire_surface.render(self.s, wire_surface.RECORDS_MARK),
                         'run: python tools/wire_surface.py --doc %s' % DOC)

    def test_the_document_does_not_describe_verbs_that_do_not_exist(self):
        """CONFIG, ACK and TX were documented as commands and never shipped.
        They may be NAMED -- the correction in section 0 has to name them --
        but never as a RADIOV10 command line."""
        real = set(self.s['commands'])
        for ghost in ('CONFIG', 'ACK', 'TX', 'AUTO_ACCEPT'):
            self.assertNotIn(ghost, real)
            self.assertNotIn('RADIOV10 %s id=' % ghost, doc(),
                             '%s is shown as a command but does not exist' % ghost)

    def test_the_dead_rx_field_names_are_not_presented_as_the_wire(self):
        """`rx_end_us` belongs to dual_format_rx, which nothing calls. It may
        appear in the correction; it must not appear in the record table."""
        self.assertNotIn('rx_end_us',
                         block(wire_surface.RECORDS_MARK) or '')
        live = [e for e in self.s['records']['RX'] if e['live']]
        self.assertEqual(len(live), 1)
        self.assertIn('time_us', live[0]['fields'])
        self.assertNotIn('rx_end_us', live[0]['fields'])

    def test_the_version_pair_is_stated_correctly(self):
        self.assertEqual(self.s['firmware_version'], '28')
        self.assertEqual(self.s['wire'], '10')
        self.assertIn('version=28 wire=10', doc())

    def test_the_id_rule_is_documented(self):
        """Undocumented, it cost three Gate A attempts."""
        self.assertIn('id_reused', doc())
        self.assertIn('last_id', doc())


class TheDeadFormattersAreDeclared(Base):
    def test_four_of_the_five_record_formatters_are_dead(self):
        self.assertEqual(self.s['dead_formatters_not_on_the_wire'],
                         ['dual_format_error', 'dual_format_rx',
                          'dual_format_txaccept', 'dual_format_txdone'])

    def test_the_one_live_formatter_is_stats(self):
        live = [e for es in self.s['records'].values() for e in es
                if e['emitter'] == 'src/dual_records.c' and e['live']]
        self.assertEqual([e['kind'] for e in live], ['STATS'])

    def test_the_document_warns_about_them(self):
        self.assertIn('мёртв', doc())

    def test_the_evidence_file_is_current(self):
        p = FIRMWARE / 'evidence/wire_surface.json'
        self.assertTrue(p.exists(), 'run python tools/wire_surface.py')
        on_disk = json.loads(p.read_text(encoding='utf-8'))
        self.assertEqual(on_disk['commands'], self.s['commands'])
        self.assertEqual(on_disk['dead_formatters_not_on_the_wire'],
                         self.s['dead_formatters_not_on_the_wire'])


if __name__ == '__main__':
    unittest.main()
